<script lang="ts">
  import { onMount } from 'svelte';
  import type { PageData } from './$types';

  export let data: PageData;
  type NoteSummary = { id:string; title:string; path:string; folder:string; pinned:boolean; updatedAt:string; revision:string; kind:string; projectId:string; excerpt:string; tags:string[]; backlinkCount:number };
  type Note = NoteSummary & { content:string; aliases:string[] };
  type Detail = { note:Note; tags:string[]; outgoing:Array<any>; backlinks:Array<any>; versions:Array<any>; outline:Array<any> };
  type View = 'write'|'split'|'read'|'graph'|'assets'|'system';
  type SystemObject = { id:string; projectId:string; kind:string; title:string; summary:string; status:string; owner:string; provenance:any; externalRef:string|null; revision:number };

  let workspace:any = data.workspace;
  let detail: Detail | null = data.note as Detail | null;
  let draft: Note | null = data.note?.note ?? null;
  let view: View = 'split';
  let query = '';
  let results: NoteSummary[] = [];
  let selectedFolder: string | null = null;
  let selectedTag: string | null = null;
  let selectedProject: string | null = draft?.projectId && draft.projectId !== 'shared' ? draft.projectId : null;
  let saveState = 'idle';
  let message = '';
  let paletteOpen = false;
  let intentOpen = false;
  let paletteQuery = '';
  let graph: any = { nodes: [], edges: [], unresolved: [] };
  let system:any = { objects: [], relations: [], views: [], stats: { objects:0, proposed:0, accepted:0 } };
  let selectedObject:SystemObject|null = null;
  let objectDraft = { title:'', summary:'' };
  let assets:any[] = workspace.assets || [];
  let trash: NoteSummary[] = [];
  let showTrash = false;
  let showImport = false;
  let showProject = false;
  let showLinkAsset = false;
  let showRun = false;
  let runProposal:any = null;
  let runGoal = '';
  let runWorkspace = '/Users/ummi/hii';
  let runModel = 'qwen3.6:27b-mlx';
  let runMaxSteps = 8;
  let sourceRoot = '/Users/ummi/Desktop/ummi';
  let importPlan:any = null;
  let linkPath = '';
  let linkName = '';
  let projectName = '';
  let editor:HTMLTextAreaElement;
  let fileInput: HTMLInputElement;
  let assetInput: HTMLInputElement;
  let saveTimer: ReturnType<typeof setTimeout> | undefined;
  let searchTimer: ReturnType<typeof setTimeout> | undefined;
  let match = draft?.revision || draft?.updatedAt || null;

  $: visibleNotes = (query.trim() ? results : workspace.notes).filter((note:NoteSummary) =>
    (!selectedProject || note.projectId === selectedProject || note.path.startsWith(`Projects/${selectedProject}/`)) &&
    (!selectedFolder || note.folder === selectedFolder) && (!selectedTag || note.tags.includes(selectedTag))
  );
  $: activeSystemView = system.views?.find((candidate:any)=>candidate.kind==='system-map') || null;
  $: systemProject = selectedProject || draft?.projectId || 'shared';

  const formatTime = (value:string) => new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value));
  const words = (value:string) => value.trim() ? value.trim().split(/\s+/).length : 0;
  const escapeHtml = (value:string) => value.replace(/[&<>"']/g,(c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c] ?? c));
  function inline(value:string) {
    return escapeHtml(value)
      .replace(/\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|([^\]]+))?\]\]/g,(_m,target,alias) => `<button type="button" class="hii-wikilink" data-wiki="${escapeHtml(target.trim())}">${escapeHtml((alias || target).trim())}</button>`)
      .replace(/!\[([^\]]*)\]\(([^)]+)\)/g,'<span class="hii-embed">asset · $1 · $2</span>')
      .replace(/`([^`]+)`/g,'<code class="hii-inline-code">$1</code>')
      .replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  }
  function markdown(value:string) {
    let inCode = false;
    return `<article class="hii-markdown-preview">${value.split('\n').map((line) => {
      if (line.startsWith('```')) { inCode = !inCode; return inCode ? '<pre class="hii-code-block"><code>' : '</code></pre>'; }
      if (inCode) return `${escapeHtml(line)}\n`;
      const heading = line.match(/^(#{1,6})\s+(.+)$/); if (heading) return `<h${Math.min(heading[1].length+1,6)} class="hii-md-heading hii-md-h${heading[1].length}">${inline(heading[2])}</h${Math.min(heading[1].length+1,6)}>`;
      const task = line.match(/^\s*-\s+\[([ xX])\]\s*(.*)$/); if (task) return `<label class="hii-md-task"><input type="checkbox" ${task[1].toLowerCase()==='x'?'checked':''} disabled> <span>${inline(task[2])}</span></label>`;
      const bullet = line.match(/^\s*[-*+]\s+(.+)$/); if (bullet) return `<div class="hii-md-bullet"><span>—</span><p>${inline(bullet[1])}</p></div>`;
      if (line.startsWith('> ')) return `<blockquote>${inline(line.slice(2))}</blockquote>`;
      if (/^---+$/.test(line.trim())) return '<hr>';
      return line.trim() ? `<p>${inline(line)}</p>` : '<div class="hii-md-space"></div>';
    }).join('')}</article>`;
  }

  async function json(url:string, init?:RequestInit) { const response=await fetch(url,init); const type=response.headers.get('content-type')||''; const body=type.includes('json')?await response.json():await response.text(); if(!response.ok) throw Object.assign(new Error(body?.error||body||'Knowledge action failed.'),{status:response.status}); return body; }
  async function refresh() { workspace=await json('/api/knowledge'); assets=workspace.assets||[]; }
  async function openNote(id:string) { detail=await json(`/api/knowledge?mode=note&id=${encodeURIComponent(id)}`); draft=detail?.note ?? null; match=draft?.revision||draft?.updatedAt||null; if(draft?.projectId&&draft.projectId!=='shared')selectedProject=draft.projectId; saveState='idle'; view=view==='system'||view==='assets'||view==='graph'?'split':view; }
  async function mutate(action:string, body:Record<string,unknown>={}) { return json('/api/knowledge',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,...body})}); }
  async function createNote(title='Untitled', folder=selectedFolder||(selectedProject?`Projects/${selectedProject}`:'Inbox')) { try { const value=await mutate('create',{title,folder,projectId:selectedProject||'shared',content:`# ${title}\n\n`}); await refresh(); await openNote(value.note.id); } catch(error){ message=error instanceof Error?error.message:'Could not create note.'; } }
  async function createProject(){ try { const value=await mutate('create-project',{name:projectName}); selectedProject=value.project.id; selectedFolder=null; selectedTag=null; projectName=''; showProject=false; await refresh(); await openNote(value.note.note.id); message=`${value.project.name} is ready with a project Home note and System Map.`; } catch(error){ message=error instanceof Error?error.message:'Could not create project.'; } }
  async function openDaily(){ const value=await mutate('daily',{date:new Date().toISOString().slice(0,10)}); await refresh(); await openNote(value.note.id); }
  async function save(){ if(!draft)return; saveState='saving'; try { detail=await mutate('save',{id:draft.id,title:draft.title,folder:draft.folder,content:draft.content,pinned:draft.pinned,aliases:draft.aliases,ifMatch:match}); draft=detail?.note??null; match=draft?.revision||draft?.updatedAt||null; saveState='saved'; await refresh(); setTimeout(()=>saveState=saveState==='saved'?'idle':saveState,1200); } catch(error:any){ saveState=error?.status===409?'conflict':'error'; message=error?.message||'Could not save note.'; } }
  function changed(){ saveState='dirty'; if(saveTimer)clearTimeout(saveTimer); saveTimer=setTimeout(save,850); }
  async function follow(title:string){ const found=workspace.notes.find((note:NoteSummary)=>note.title.toLowerCase()===title.toLowerCase()); found?await openNote(found.id):await createNote(title,draft?.folder||''); }
  async function trashCurrent(){ if(!draft)return; await mutate('trash',{id:draft.id}); draft=null; detail=null; await refresh(); }
  async function loadTrash(){ const value=await json('/api/knowledge?mode=trash'); trash=value.notes||[]; showTrash=true; }
  async function restore(id:string){ await mutate('restore',{id}); await refresh(); await loadTrash(); await openNote(id); }
  async function loadGraph(){ graph=await json('/api/knowledge?mode=graph'); view='graph'; }
  async function importFiles(files:FileList|null){ if(!files?.length)return; const payload=await Promise.all(Array.from(files).slice(0,200).map(async file=>({name:file.name,path:(file as any).webkitRelativePath||file.name,content:await file.text()}))); const value=await mutate('import',{files:payload}); await refresh(); if(value.notes?.[0]?.note?.id)await openNote(value.notes[0].note.id); message=`Imported ${value.notes?.length||0} notes into HII knowledge.`; }
  async function copyAssets(files:FileList|null){ if(!files?.length)return; for(const file of Array.from(files).slice(0,24)){ const bytes=new Uint8Array(await file.arrayBuffer()); let binary=''; for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000)); await mutate('asset-copy',{projectId:selectedProject||'Shared',name:file.name,mime:file.type,contentBase64:btoa(binary)}); } await loadAssets(); message=`Copied ${files.length} asset${files.length===1?'':'s'} into HII-managed storage.`; }
  async function linkAsset(){ try{await mutate('asset-link',{projectId:selectedProject||'Shared',sourcePath:linkPath,name:linkName||undefined});showLinkAsset=false;linkPath='';linkName='';await loadAssets();message='Linked asset indexed without copying it.';}catch(error){message=error instanceof Error?error.message:'Could not link asset.';} }
  async function loadAssets(){ const value=await json('/api/knowledge?mode=assets');assets=value.assets||[];view='assets'; }
  function search(){ if(searchTimer)clearTimeout(searchTimer); if(!query.trim()){results=[];return;} searchTimer=setTimeout(async()=>{ const value=await json(`/api/knowledge?mode=search&q=${encodeURIComponent(query)}`); results=value.results||[]; },180); }
  function previewActivate(event:MouseEvent|KeyboardEvent){ if(event instanceof KeyboardEvent && !['Enter',' '].includes(event.key))return; const target=(event.target as HTMLElement).closest<HTMLElement>('[data-wiki]'); if(target?.dataset.wiki) void follow(target.dataset.wiki); }
  function graphActivate(event:KeyboardEvent,id:string){ if(['Enter',' '].includes(event.key)){event.preventDefault();void openNote(id);view='split';} }
  function closePalette(event:MouseEvent|KeyboardEvent){ if(event instanceof KeyboardEvent && event.key!=='Escape')return; if(event instanceof KeyboardEvent || event.target===event.currentTarget){paletteOpen=false;intentOpen=false;} }
  async function planImport(){ try{importPlan=await mutate('plan-import',{sourceRoot});message=importPlan.status==='completed'?`This exact ${importPlan.manifest.totals.files}-file source is already merged and verified.`:`Ready to merge ${importPlan.manifest.totals.files} files into HII. Review the counts, then approve.`;}catch(error){message=error instanceof Error?error.message:'Could not plan the import.';} }
  async function executeImport(){ if(!importPlan?.approvalToken)return;try{const result=await mutate('execute-import',{batchId:importPlan.batchId,planHash:importPlan.planHash,approvalToken:importPlan.approvalToken});await refresh();showImport=false;message=result.ok?`Merged and verified ${result.storedFiles} files into canonical HII knowledge.`:'Import completed but verification needs review.';}catch(error){message=error instanceof Error?error.message:'Could not execute the import.';} }
  async function rebuildIndex(){ const value=await mutate('rebuild-index');workspace=value.workspace;message='Derived HII search, tag, and link indexes rebuilt.'; }

  async function loadSystem(project=systemProject){ system=await json(`/api/knowledge?mode=systems&project=${encodeURIComponent(project||'shared')}`); view='system'; selectedObject=null; }
  async function exploreSystem(){ if(!draft){message='Open a source note first.';return;} const value=await mutate('explore-system',{noteId:draft.id});system=value.snapshot;selectedProject=value.projectId==='shared'?selectedProject:value.projectId;view='system';intentOpen=false;message=`Proposed ${value.objects.length} source-linked system objects for review.`; }
  function selectObject(object:SystemObject){selectedObject=object;objectDraft={title:object.title,summary:object.summary};}
  async function reviewObject(status:'accepted'|'rejected'){if(!selectedObject)return;const value=await mutate('object-update',{id:selectedObject.id,status,ifRevision:selectedObject.revision});selectedObject=value.object;objectDraft={title:value.object.title,summary:value.object.summary};await loadSystem(value.object.projectId);selectedObject=value.object;message=status==='accepted'?'Object accepted into project knowledge.':'Proposal rejected; source evidence remains intact.';}
  async function saveObject(){if(!selectedObject)return;const value=await mutate('object-update',{id:selectedObject.id,title:objectDraft.title,summary:objectDraft.summary,ifRevision:selectedObject.revision});selectedObject=value.object;await loadSystem(value.object.projectId);selectedObject=value.object;}
  async function reviewRelation(id:string,status:'accepted'|'rejected'){await mutate('relation-update',{id,status});await loadSystem(systemProject);}
  async function makeTask(){if(!selectedObject)return;const value=await mutate('object-to-task',{id:selectedObject.id,projectId:selectedObject.projectId});await loadSystem(selectedObject.projectId);message=`Created bounded board task: ${value.task.title}`;}
  function openRunApproval(run:SystemObject){runProposal={object:run,proposal:{}};runGoal=run.summary.replace(/^Bounded local execution proposal\. Goal:\s*/, '');showRun=true;}
  function openSelectedRunApproval(){if(selectedObject)openRunApproval(selectedObject);}
  async function prepareRun(){if(!selectedObject)return;try{const value=await mutate('prepare-run',{id:selectedObject.id,projectId:selectedObject.projectId});runProposal=value;runGoal=value.proposal.goal;runWorkspace=value.proposal.workspaceRoot;runModel=value.proposal.model;runMaxSteps=value.proposal.maxSteps;showRun=true;await loadSystem(value.object.projectId);const current:SystemObject=system.objects.find((object:SystemObject)=>object.id===value.object.id)||value.object;selectedObject=current;objectDraft={title:current.title,summary:current.summary};message='Run proposal is ready for permission review. Nothing has executed.';}catch(error){message=error instanceof Error?error.message:'Could not prepare the run.';}}
  async function approveRun(){if(!runProposal?.object?.id)return;try{const value=await mutate('approve-run',{runId:runProposal.object.id,goal:runGoal,workspaceRoot:runWorkspace,model:runModel,maxSteps:runMaxSteps,approved:true});showRun=false;await loadSystem(value.object.projectId);const current:SystemObject=system.objects.find((object:SystemObject)=>object.id===value.object.id)||value.object;selectedObject=current;objectDraft={title:current.title,summary:current.summary};message='Approved run queued with AII. Use Refresh run to pull proof and its receipt back into this map.';}catch(error){message=error instanceof Error?error.message:'Could not approve the run.';}}
  async function syncRun(){if(!selectedObject)return;try{const id=selectedObject.id;const project=selectedObject.projectId;const value=await mutate('sync-run',{runId:id});await loadSystem(project);const current:SystemObject=system.objects.find((object:SystemObject)=>object.id===id)||value.object;selectedObject=current;objectDraft={title:current.title,summary:current.summary};message=value.created?.length?`Run ${value.job.status}. Added ${value.created.length} proof and receipt object${value.created.length===1?'':'s'} to this map.`:`Run is ${value.job.status}; no new proof objects yet.`;}catch(error){message=error instanceof Error?error.message:'Could not refresh the run.';}}
  async function pinObject(){if(!selectedObject)return;const value=await mutate('pin-object',{id:selectedObject.id,projectId:selectedObject.projectId});message=value.alreadyPinned?'Object is already pinned on the HII canvas.':'Canonical object pinned to the HII canvas.';}
  async function promoteSelection(kind:'idea'|'decision'|'constraint') { if(!draft||!editor)return;const start=editor.selectionStart,end=editor.selectionEnd;const selected=draft.content.slice(start,end).trim();if(!selected){message='Select text in the editor first.';return;}const lineStart=draft.content.slice(0,start).split('\n').length;const value=await mutate('object-create',{projectId:draft.projectId,kind,title:selected.slice(0,90),summary:selected,status:'proposed',provenance:{noteId:draft.id,path:draft.path,lineStart,lineEnd:lineStart+selected.split('\n').length-1,contentHash:draft.revision,confidence:1}});intentOpen=false;await loadSystem(draft.projectId);selectedObject=value.object;message=`Proposed ${kind} created for review.`; }
  function position(id:string,index:number){const saved=activeSystemView?.layout?.find((item:any)=>item.objectId===id);return saved||{objectId:id,x:40+(index%4)*260,y:48+Math.floor(index/4)*180,w:228,h:132};}
  function objectIndex(id:string){return system.objects.findIndex((object:SystemObject)=>object.id===id);}
  function edge(relation:any){const from=position(relation.fromId,objectIndex(relation.fromId));const to=position(relation.toId,objectIndex(relation.toId));return{x1:from.x+from.w/2,y1:from.y+from.h/2,x2:to.x+to.w/2,y2:to.y+to.h/2};}
  function dragSystem(event:PointerEvent,object:SystemObject){const element=event.currentTarget as HTMLElement;if((event.target as HTMLElement).closest('button,input,textarea'))return;event.preventDefault();const item=position(object.id,objectIndex(object.id));const sx=event.clientX,sy=event.clientY,ox=item.x,oy=item.y;const move=(next:PointerEvent)=>{const layout=(activeSystemView?.layout||system.objects.map((candidate:SystemObject,index:number)=>position(candidate.id,index))).map((candidate:any)=>candidate.objectId===object.id?{...candidate,x:ox+next.clientX-sx,y:oy+next.clientY-sy}:candidate);system={...system,views:system.views.map((candidate:any)=>candidate.id===activeSystemView?.id?{...candidate,layout}:candidate)};};const up=async()=>{removeEventListener('pointermove',move);removeEventListener('pointerup',up);if(activeSystemView)await mutate('view-save',{...activeSystemView,layout:activeSystemView.layout});};addEventListener('pointermove',move);addEventListener('pointerup',up);element.setPointerCapture?.(event.pointerId);}

</script>

<svelte:head><title>HII / Knowledge</title></svelte:head>
<main class="hii-knowledge-workspace">
  <aside class="hii-knowledge-sidebar">
    <div class="hii-knowledge-search-wrap"><span>⌕</span><input bind:value={query} on:input={search} placeholder="Search notes, ideas, assets" aria-label="Search knowledge" /><kbd>⌘K</kbd></div>
    <div class="hii-knowledge-actions"><button on:click={()=>createNote()}>＋ note</button><button on:click={openDaily}>◫ today</button><button on:click={()=>fileInput.click()}>⇧ import</button><input bind:this={fileInput} type="file" accept=".md,.markdown,.txt" multiple hidden on:change={(event)=>importFiles(event.currentTarget.files)} /></div>
    <div class="hii-knowledge-navscroll">
      <section class="hii-knowledge-navsection"><h2>Workspace <span>{workspace.stats.notes}</span></h2><button class:is-active={!selectedProject&&!selectedFolder&&!selectedTag} on:click={()=>{selectedProject=null;selectedFolder=null;selectedTag=null;view='split'}}>⌂ All knowledge <b>{workspace.notes.length}</b></button><button class:is-active={selectedFolder==='Inbox'} on:click={()=>{selectedFolder='Inbox';selectedProject=null;selectedTag=null}}>↓ Inbox <b>{workspace.notes.filter((note:NoteSummary)=>note.folder==='Inbox').length}</b></button><button class:is-active={selectedFolder==='Daily'} on:click={()=>{selectedFolder='Daily';selectedProject=null;selectedTag=null}}>◫ Daily</button><button class:is-active={view==='assets'} on:click={loadAssets}>▧ Assets <b>{workspace.stats.assets||0}</b></button></section>
      <section class="hii-knowledge-navsection"><h2>Projects <span>{workspace.projects?.length||0}<button class="hii-section-add" aria-label="Create project" on:click={()=>showProject=true}>＋</button></span></h2>{#each workspace.projects||[] as project}<button class:is-active={selectedProject===project.id} on:click={()=>{selectedProject=project.id;selectedFolder=null;selectedTag=null;view='split'}}>⌙ {project.name}<b>{project.noteCount}</b></button>{/each}</section>
      <section class="hii-knowledge-navsection"><h2>Folders <span>{workspace.folders.length}</span></h2>{#each workspace.folders as folder}<button class:is-active={selectedFolder===folder.folder} on:click={()=>{selectedFolder=folder.folder;selectedProject=null;selectedTag=null}}>⌙ {folder.folder||'Root'} <b>{folder.count}</b></button>{/each}</section>
      <section class="hii-knowledge-navsection"><h2>Tags <span>{workspace.tags.length}</span></h2>{#each workspace.tags.slice(0,24) as tag}<button class:is-active={selectedTag===tag.tag} on:click={()=>{selectedTag=tag.tag;selectedFolder=null}}># {tag.tag} <b>{tag.count}</b></button>{/each}</section>
      <section class="hii-knowledge-navsection"><h2>Views</h2><button class:is-active={view==='system'} on:click={()=>loadSystem()}>⌬ System Map <b>{workspace.stats.objects||0}</b></button><button class:is-active={view==='graph'} on:click={loadGraph}>◎ Knowledge graph <b>{workspace.stats.links}</b></button><button on:click={loadTrash}>⌫ Trash <b>{workspace.trashCount}</b></button></section>
    </div>
    <div class="hii-knowledge-db"><button on:click={()=>showImport=true}><span><i></i> HII knowledge authority</span><code title={workspace.dbPath}>{workspace.dbPath}</code></button><small>Import sources stay immutable; export remains portable</small></div>
  </aside>

  <section class="hii-knowledge-index"><header><div><span class="hii-knowledge-eyebrow">{query?'Search':selectedTag?`#${selectedTag}`:selectedProject||selectedFolder||'All knowledge'}</span><h1>{visibleNotes.length} {visibleNotes.length===1?'note':'notes'}</h1></div><button on:click={()=>paletteOpen=true} aria-label="Open command palette">⌘</button></header><div class="hii-knowledge-note-list">{#each visibleNotes as note}<button class:is-active={draft?.id===note.id} on:click={()=>openNote(note.id)}><span class="hii-note-title">{note.pinned?'◆':''}{note.title}</span><span class="hii-note-path">{note.path}</span><span class="hii-note-excerpt">{note.excerpt||'Empty note'}</span><span class="hii-note-meta"><time>{note.updatedAt?formatTime(note.updatedAt):'match'}</time><span>{note.backlinkCount!==undefined?`${note.backlinkCount}↙`:''}</span></span></button>{/each}{#if visibleNotes.length===0}<div class="hii-knowledge-empty"><strong>Nothing matched.</strong><span>Create a note or import Markdown.</span><button on:click={()=>createNote()}>Create first note</button></div>{/if}</div></section>

  <section class="hii-knowledge-main">
    <div class="hii-knowledge-toolbar"><div class="hii-view-switch" role="group" aria-label="Knowledge view">{#each ['write','split','read'] as mode}<button class:is-active={view===mode} on:click={()=>view=mode as View}>{mode}</button>{/each}<button class:is-active={view==='system'} on:click={()=>loadSystem()}>system</button><button class:is-active={view==='graph'} on:click={loadGraph}>graph</button><button class:is-active={view==='assets'} on:click={loadAssets}>assets</button></div><div class="hii-save-state" data-state={saveState}><i></i> {saveState==='idle'?'local':saveState}</div>{#if draft}<div class="hii-note-tools"><button on:click={()=>intentOpen=true}>⌘I act</button><button on:click={()=>{if(draft){draft.pinned=!draft.pinned;changed()}}}>{draft.pinned?'◆ pinned':'◇ pin'}</button><a href={`/api/knowledge?mode=export-note&id=${draft.id}`}>↓ .md</a><button on:click={trashCurrent}>⌫</button></div>{/if}</div>

    {#if view==='graph'}<div class="hii-knowledge-graph-page"><div class="hii-graph-heading"><span>Knowledge constellation</span><small>{graph.nodes.length} notes / {graph.edges.length} resolved links / {graph.unresolved.length} unresolved</small></div><div class="hii-graph-wrap"><svg viewBox="0 0 900 620" role="img" aria-label="Knowledge graph">{#each graph.edges as edge,index}<line x1={100+(index%7)*110} y1={140+(index%3)*130} x2={180+((index+2)%7)*100} y2={180+((index+1)%3)*130}></line>{/each}{#each graph.nodes as node,index}<g class="hii-graph-node" class:is-selected={node.id===draft?.id} role="button" tabindex="0" on:click={()=>{openNote(node.id);view='split'}} on:keydown={(event)=>graphActivate(event,node.id)}><circle cx={100+(index%7)*110} cy={120+Math.floor(index/7)*180} r={Math.min(11+Number(node.degree)*1.6,24)}></circle><text x={100+(index%7)*110} y={150+Math.floor(index/7)*180} text-anchor="middle">{node.title.slice(0,24)}</text></g>{/each}</svg></div></div>
    {:else if view==='assets'}<div class="hii-assets-page"><header><div><span>Project asset library</span><small>Copy into the vault or keep an explicit external link.</small></div><div><button on:click={()=>assetInput.click()}>＋ copy files</button><input bind:this={assetInput} type="file" multiple hidden on:change={(event)=>copyAssets(event.currentTarget.files)} /><button on:click={()=>showLinkAsset=true}>↗ link path</button></div></header><div class="hii-asset-grid">{#each assets.filter((asset:any)=>!selectedProject||asset.projectId===selectedProject) as asset}<article class:missing={!asset.available}><div class="hii-asset-preview">{#if asset.available&&asset.mime.startsWith('image/')}<img src={`/api/knowledge?mode=asset-file&id=${asset.id}`} alt={asset.name} />{:else}<span>{asset.mime.split('/')[0]||'file'}</span>{/if}</div><strong>{asset.name}</strong><span>{asset.mode} · {(asset.size/1024).toFixed(1)} KB</span><code>{asset.path||asset.sourcePath}</code><small>{asset.available?'available':'missing source'}</small></article>{/each}{#if assets.length===0}<div class="hii-knowledge-empty"><strong>No assets yet.</strong><span>Copy a file into the project or link an existing file in place.</span></div>{/if}</div></div>
    {:else if view==='system'}<div class="hii-system-layout"><section class="hii-system-stage"><header><div><span>{systemProject} / System Map</span><small>{system.stats?.accepted||0} accepted · {system.stats?.proposed||0} awaiting review</small></div>{#if draft}<button on:click={exploreSystem}>Explore “{draft.title}” as system</button>{/if}</header><div class="hii-system-canvas"><svg aria-hidden="true">{#each system.relations.filter((relation:any)=>relation.status!=='rejected') as relation}{@const line=edge(relation)}<line class:proposed={relation.status==='proposed'} x1={line.x1} y1={line.y1} x2={line.x2} y2={line.y2}></line>{/each}</svg>{#each system.objects.filter((object:SystemObject)=>object.status!=='rejected') as object,index}{@const item=position(object.id,index)}<button class="hii-system-object" class:is-selected={selectedObject?.id===object.id} class:is-proposed={object.status==='proposed'} data-kind={object.kind} style={`left:${item.x}px;top:${item.y}px;width:${item.w}px;height:${item.h}px`} on:pointerdown={(event)=>dragSystem(event,object)} on:click={()=>selectObject(object)}><span>{object.kind}</span><strong>{object.title}</strong><small>{object.status}</small></button>{/each}{#if system.objects.length===0}<div class="hii-system-empty"><strong>Turn knowledge into a shared model.</strong><p>Open a project note, then use Explore as system. HII will propose source-linked actors, intentions, constraints, components, alternatives, and decisions for your review.</p></div>{/if}</div><footer><span>Proposal</span><span>Accepted knowledge</span><span>Execution and proof</span></footer></section><aside class="hii-system-inspector">{#if selectedObject}<header><span>{selectedObject.kind}</span><b>{selectedObject.status}</b></header><label>Title<input bind:value={objectDraft.title} /></label><label>Summary<textarea bind:value={objectDraft.summary}></textarea></label><section><h2>Provenance</h2>{#if selectedObject.provenance}<code>{selectedObject.provenance.path}:L{selectedObject.provenance.lineStart}</code><span>confidence {Math.round(selectedObject.provenance.confidence*100)}%</span><span>hash {selectedObject.provenance.contentHash.slice(0,12)}</span>{:else}<span>No source attached.</span>{/if}{#if selectedObject.externalRef}<code>{selectedObject.externalRef}</code>{/if}</section><section><h2>Relationships</h2>{#each system.relations.filter((relation:any)=>relation.fromId===selectedObject?.id||relation.toId===selectedObject?.id) as relation}<div class="hii-relation-row"><span>{relation.kind}</span><b>{relation.status}</b>{#if relation.status==='proposed'}<button on:click={()=>reviewRelation(relation.id,'accepted')}>accept</button><button on:click={()=>reviewRelation(relation.id,'rejected')}>reject</button>{/if}</div>{/each}</section><div class="hii-inspector-actions"><button on:click={saveObject}>Save edit</button>{#if selectedObject.status==='proposed'&&selectedObject.kind!=='run'}<button class="primary" on:click={()=>reviewObject('accepted')}>Accept ⌘↵</button><button on:click={()=>reviewObject('rejected')}>Reject</button>{/if}{#if selectedObject.kind==='decision'&&['accepted','active'].includes(selectedObject.status)}<button on:click={makeTask}>Convert to task</button>{/if}{#if ['task','decision'].includes(selectedObject.kind)&&['accepted','active'].includes(selectedObject.status)}<button on:click={prepareRun}>Prepare bounded run</button>{/if}{#if selectedObject.kind==='run'&&selectedObject.status==='proposed'}<button class="primary" on:click={openSelectedRunApproval}>Review permissions + approve</button>{/if}{#if selectedObject.kind==='run'&&['active','completed','blocked'].includes(selectedObject.status)}<button on:click={syncRun}>Refresh run + proof</button>{/if}<button on:click={pinObject}>Pin to HII canvas</button></div>{:else}<div class="hii-system-empty"><strong>Select an object</strong><p>Inspect identity, evidence, relationships, state, and available actions here.</p></div>{/if}</aside></div>
    {:else if draft}<div class={`hii-editor-grid is-${view}`}>{#if view!=='read'}<div class="hii-editor-pane"><div class="hii-note-properties"><input class="hii-note-title-input" bind:value={draft.title} on:input={changed} aria-label="Note title" /><div class="hii-note-property-row"><span>folder</span><input bind:value={draft.folder} on:input={changed} placeholder="Inbox" /><span>{words(draft.content)} words</span></div></div><textarea bind:this={editor} class="hii-markdown-editor" bind:value={draft.content} on:input={changed} spellcheck="true" aria-label="Markdown editor"></textarea></div>{/if}{#if view!=='write'}<!-- svelte-ignore a11y_no_noninteractive_element_interactions --><div class="hii-preview-pane" role="region" aria-label="Rendered note preview" tabindex="-1" on:click={previewActivate} on:keydown={previewActivate}>{@html markdown(draft.content)}</div>{/if}<aside class="hii-knowledge-context"><section><h2>Identity</h2><code>{draft.kind} · {draft.projectId}</code><span>revision {draft.revision.slice(0,12)}</span></section><section><h2>Outline <span>{detail?.outline.length||0}</span></h2>{#each detail?.outline||[] as item}<button>{item.text}<b>L{item.line}</b></button>{/each}</section><section><h2>Backlinks <span>{detail?.backlinks.length||0}</span></h2>{#each detail?.backlinks||[] as link}<button on:click={()=>openNote(link.sourceNoteId)}>↙ {link.sourceTitle}</button>{/each}</section><section><h2>Outgoing <span>{detail?.outgoing.length||0}</span></h2>{#each detail?.outgoing||[] as link}<button on:click={()=>follow(link.targetTitle)}>↗ {link.targetTitle}</button>{/each}</section><section><h2>Tags <span>{detail?.tags.length||0}</span></h2><div class="hii-context-tags">{#each detail?.tags||[] as tag}<button on:click={()=>{selectedTag=tag;selectedFolder=null}}>#{tag}</button>{/each}</div></section><section><h2>History <span>{detail?.versions.length||0}</span></h2>{#each (detail?.versions||[]).slice(0,8) as version}<button>v{version.version}<b>{formatTime(version.createdAt)}</b></button>{/each}</section></aside></div>
    {:else}<div class="hii-knowledge-welcome"><span class="hii-knowledge-kicker">Human Information Interface</span><h1>Make thought<br />stay useful.</h1><p>Canonical HII knowledge, portable exports, linked assets, systems thinking, agent receipts, and a graph that grows from real work.</p><div><button on:click={()=>createNote('Start here')}>Create a note</button><button on:click={openDaily}>Open today</button></div></div>{/if}
    {#if message}<div class="hii-knowledge-toast" role="status"><span>{message}</span><button on:click={()=>message=''}>×</button></div>{/if}
  </section>

  {#if showTrash}<div class="hii-knowledge-modal" role="dialog" aria-modal="true" aria-label="Trash" tabindex="-1"><div class="hii-modal-card"><header><h2>Trash</h2><button on:click={()=>showTrash=false}>×</button></header>{#each trash as note}<div class="hii-trash-row"><div><strong>{note.title}</strong><span>{note.path}</span></div><button on:click={()=>restore(note.id)}>Restore</button></div>{/each}</div></div>{/if}
  {#if showProject}<div class="hii-knowledge-modal" role="dialog" aria-modal="true" aria-label="Create project" tabindex="-1"><div class="hii-modal-card hii-vault-card"><header><div><span>First-class knowledge scope</span><h2>New project</h2></div><button on:click={()=>showProject=false}>×</button></header><p>HII creates a project Home note and saved System Map in canonical knowledge. Portable Markdown export stays available.</p><label>Project name<input bind:value={projectName} placeholder="Project name" on:keydown={(event)=>{if(event.key==='Enter')void createProject()}} /></label><div class="hii-modal-actions"><button on:click={()=>showProject=false}>Cancel</button><button class="primary" on:click={createProject}>Create project</button></div></div></div>{/if}
  {#if showImport}<div class="hii-knowledge-modal" role="dialog" aria-modal="true" aria-label="Merge knowledge" tabindex="-1"><div class="hii-modal-card hii-vault-card"><header><div><span>HII canonical knowledge</span><h2>Merge a complete vault</h2></div><button on:click={()=>showImport=false}>×</button></header><p>HII inventories and hash-locks the source before importing. Source files remain unchanged and HII becomes the canonical working instance.</p><label>Source vault<input bind:value={sourceRoot} placeholder="/Users/you/Obsidian" /></label>{#if importPlan}<div class="hii-note-properties"><span>{importPlan.manifest.totals.files} supported files</span><span>{importPlan.manifest.totals.markdown} Markdown</span><span>{importPlan.manifest.totals.links} links</span><span>{importPlan.manifest.totals.excluded} exclusions</span><span>{importPlan.manifest.conflicts.length} conflicts retained for review</span>{#if importPlan.status==='completed'}<span>Already merged · verified</span>{/if}</div>{/if}<div class="hii-modal-actions"><button on:click={rebuildIndex}>Rebuild derived indexes</button>{#if importPlan?.status==='completed'}<button class="primary" disabled>Already merged</button>{:else if importPlan?.approvalToken}<button class="primary" on:click={executeImport}>Approve merge into HII</button>{:else}<button class="primary" on:click={planImport}>Preview import</button>{/if}</div></div></div>{/if}
  {#if showLinkAsset}<div class="hii-knowledge-modal" role="dialog" aria-modal="true" aria-label="Link asset" tabindex="-1"><div class="hii-modal-card hii-vault-card"><header><h2>Link existing asset</h2><button on:click={()=>showLinkAsset=false}>×</button></header><p>The file stays where it is. HII stores its approved path, hash, metadata, and availability.</p><label>Absolute file path<input bind:value={linkPath} placeholder="/Users/you/Projects/model.3dm" /></label><label>Display name<input bind:value={linkName} placeholder="Optional" /></label><div class="hii-modal-actions"><button class="primary" on:click={linkAsset}>Link asset</button></div></div></div>{/if}
  {#if showRun}<div class="hii-knowledge-modal" role="dialog" aria-modal="true" aria-label="Approve bounded run" tabindex="-1"><div class="hii-modal-card hii-vault-card"><header><div><span>Knowledge → Agent → Receipt</span><h2>Approve bounded local run</h2></div><button on:click={()=>showRun=false}>×</button></header><p>HII will hand this approved intent to AII. AII runs the local workspace agent; proof and its receipt return to this System Map when you refresh the run.</p><label>Goal<textarea bind:value={runGoal}></textarea></label><label>Approved workspace root<input bind:value={runWorkspace} /></label><label>Local model<select bind:value={runModel}><option value="qwen3.6:27b-mlx">Qwen 27B · workhorse</option><option value="qwen3.6:35b-mlx">Qwen 35B · deeper</option></select></label><label>Maximum tool steps<input type="number" min="1" max="24" bind:value={runMaxSteps} /></label><div class="hii-note-properties"><span>local only</span><span>selected workspace only</span><span>no publish / push / spend / message</span><span>verification + receipt required</span></div><div class="hii-modal-actions"><button on:click={()=>showRun=false}>Keep as proposal</button><button class="primary" on:click={approveRun}>Approve and queue with AII</button></div></div></div>{/if}
  {#if paletteOpen}<div class="hii-command-overlay" role="dialog" aria-modal="true" aria-label="Knowledge command palette" tabindex="-1" on:click={closePalette} on:keydown={closePalette}><div class="hii-command-palette"><div class="hii-command-input"><span>⌘K</span><input bind:value={paletteQuery} placeholder="Search, navigate, or create…" /></div><div class="hii-command-results"><button on:click={()=>{createNote();paletteOpen=false}}><span>New note</span><kbd>⌘N</kbd></button><button on:click={()=>{openDaily();paletteOpen=false}}><span>Open today</span><kbd>daily</kbd></button><button on:click={()=>{loadSystem();paletteOpen=false}}><span>Open System Map</span><kbd>objects</kbd></button><button on:click={()=>{loadAssets();paletteOpen=false}}><span>Open asset library</span><kbd>files</kbd></button>{#each workspace.notes.filter((note:NoteSummary)=>note.title.toLowerCase().includes(paletteQuery.toLowerCase())).slice(0,20) as note}<button on:click={()=>{openNote(note.id);paletteOpen=false}}><span>{note.title}</span><kbd>{note.folder||'root'}</kbd></button>{/each}</div></div></div>{/if}
  {#if intentOpen}<div class="hii-command-overlay hii-intent-overlay" role="dialog" aria-modal="true" aria-label="Contextual intent" tabindex="-1" on:click={closePalette} on:keydown={closePalette}><div class="hii-command-palette"><div class="hii-command-input"><span>⌘I</span><div><strong>What do you want to happen?</strong><small>Context: {draft?.title||selectedObject?.title||selectedProject||'Knowledge Workspace'}</small></div></div><div class="hii-command-results">{#if draft}<button on:click={exploreSystem}><span>Explore as system</span><kbd>propose objects + relations</kbd></button><button on:click={()=>promoteSelection('idea')}><span>Selection → idea</span><kbd>review first</kbd></button><button on:click={()=>promoteSelection('decision')}><span>Selection → decision</span><kbd>review first</kbd></button><button on:click={()=>promoteSelection('constraint')}><span>Selection → constraint</span><kbd>review first</kbd></button>{/if}<button on:click={()=>{createNote();intentOpen=false}}><span>Create note in current scope</span><kbd>{selectedProject||'Inbox'}</kbd></button><button on:click={()=>{loadAssets();intentOpen=false}}><span>Add or inspect assets</span><kbd>copy / link</kbd></button><button on:click={()=>{loadSystem();intentOpen=false}}><span>Inspect project system</span><kbd>truth + relationships</kbd></button></div></div></div>{/if}
</main>
